import{z as o,x as i,o as B,c as p,q as t,j as s,D as e,d as r,s as A,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"LRU / PLRU","description":"","frontmatter":{"title":"LRU / PLRU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lru-plru.md","filePath":"cs/lru-plru.md","lastUpdated":1791063341000}'),R={name:"cs/lru-plru.md"};function d(L,a,U,P,D,c){const l=i("Mermaid");return B(),p("div",null,[a[2]||(a[2]=t('<h1 id="lru-plru" tabindex="-1">LRU / PLRU <a class="header-anchor" href="#lru-plru" aria-label="Permalink to &quot;LRU / PLRU&quot;">​</a></h1><div class="epigraph"><p>组相联要在缺失时丢掉「最可能不再用」的那一路；真 LRU 的状态随路数阶乘涨，树状伪 LRU 用少得多的位逼近。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Belady 最优替换的对照 整理</footer></div><p><a href="/cs/deep-pipeline-clock">上一课</a> 收束乱序前端，下一条路是存储层次。<a href="/cs/locality-principle">局部性</a> 已经要求「留下最近用的」。<a href="/cs/cache-miss-types">缺失分类</a> 把冲突与容量分开。本课不重讲五级的 cache 时序。缺口是<strong>组相联里具体怎么选牺牲者：真 LRU 与工业常用的 PLRU</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接映射没有替换：索引唯一决定路。2–16 路时，缺失要在组内挑一块踢掉。Belady 的 MIN 需要未来引用，硬件没有。栈算法意义上的 LRU：丢掉最久未访问的那路，对许多访问模式接近 MIN。但 \\(n\\) 路真 LRU 要记 \\(n!\\) 种排列或至少 \\(n\\log n\\) 量级的年龄，16 路已经烦。缺口不是更大的 cache，而是<strong>用可实现的位实现「接近 LRU」</strong>。</p><p><span class="marginnote">数字实例：16 路组里，真 LRU 约要 \\(16\\times 4=64\\) 位级别的时间戳；树状 PLRU 只需 \\(n-1=15\\) 位一棵满二叉树。状态位少 4 倍，时钟频率友好，这就是工业 CPU 普遍选 PLRU 的算账方式。</span></p><p><span class="marginnote">PLRU：满二叉树，每个内节点一位指向「更 LRU 的一侧」。命中把路径拨向对方；替换沿指针走到叶子。位数是 \\(n-1\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>真 LRU：组内维护年龄链或时间戳，命中则提到 MRU，替换踢 LRU。PLRU：命中沿根到该路把各位翻成「另一侧更老」；替换从根跟随「老侧」指针。随机/轮转更便宜，冲突模式下更差。</p><p><span class="marginnote">直觉类比：PLRU 的每个树位像走廊岔口的路标，箭头指向「这边更久没人用」；有客人入住（命中某路）就把沿途路标全拨向对面，要腾房（替换）时从大门跟着箭头走，走到哪间就清哪间。</span></p>',10)),(B(),s(n,null,{default:e(()=>[A(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E7%BB%84%E5%86%85%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20LRU%5B%22%E7%9C%9F%20LRU%EF%BC%9A%E8%B8%A2%E6%9C%80%E4%B9%85%E6%9C%AA%E7%94%A8%22%5D%0A%20%20MISS%20--%3E%20PLRU%5B%22PLRU%EF%BC%9A%E6%B2%BF%E6%A0%91%E6%8C%87%E9%92%88%E8%B8%A2%22%5D%0A%20%20HIT%5B%22%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20UPD%5B%22%E6%8A%8A%E8%AF%A5%E8%B7%AF%E6%A0%87%E4%B8%BA%20MRU%20%2F%20%E6%8B%A8%E6%A0%91%E4%BD%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"写回 cache：被踢的若脏则先写回，替换延迟叠在缺失上。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"冲突缺失对 LRU 敏感：循环扫描刚好大于组的工作集时，LRU 会系统性踢「即将再用」的块（scan 颠簸）。这是下一课 RRIP 要打的点，本课只承认 LRU 不是万能。PLRU 在真 LRU 与随机之间：大多数 SPECint 差距小，实现频率更好。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易把 PLRU 当成「真 LRU 的便宜等价物」。它只保证刚命中的路不会被立刻选中，不保证牺牲者恰是最久未用者；扫描大数组时它照样把「马上要用」的块挤出去。便宜是有代价的，代价由替换质量买单。")],-1)),(B(),s(n,null,{default:e(()=>[A(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E7%BC%BA%E5%A4%B1%3A%20%E4%BB%8E%E6%A0%B9%E6%B2%BF%E4%BD%8D%E4%B8%8B%E8%A1%8C%22%5D%20--%3E%20Q0%7B%22%E6%A0%B9%E4%BD%8D%E6%8C%87%E5%90%91%E5%93%AA%E5%8D%8A%3F%22%7D%0A%20%20Q0%20--%3E%7C%22%E6%9B%B4%E8%80%81%E7%9A%84%E5%8D%8A%E7%BB%84%22%7C%20HALF%5B%22%E8%BF%9B%E5%85%A5%20%E8%B7%AF0%2F%E8%B7%AF1%20%E5%8D%8A%E7%BB%84%22%5D%0A%20%20HALF%20--%3E%20Q1%7B%22%E4%B8%8B%E4%B8%80%E4%BD%8D%E6%8C%87%E5%90%91%E5%93%AA%E8%B7%AF%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%9B%B4%E8%80%81%E7%9A%84%E4%B8%80%E8%B7%AF%22%7C%20VICT%5B%22%E9%80%89%E4%B8%AD%E7%89%BA%E7%89%B2%E8%B7%AF%2C%20%E6%8D%A2%E5%85%A5%E6%96%B0%E5%9D%97%22%5D%0A%20%20HITP%5B%22%E5%91%BD%E4%B8%AD%E6%9F%90%E4%B8%80%E8%B7%AF%22%5D%20--%3E%20FLIP%5B%22%E6%8A%8A%E6%A0%B9%E5%88%B0%E8%AF%A5%E5%8F%B6%E7%9A%84%E5%90%84%E4%BD%8D%E7%BF%BB%E5%90%91%E5%88%AB%E4%BE%A7%22%5D%0A%20%20FLIP%20--%3E%20NEXT%5B%22%E6%9B%BF%E6%8D%A2%E6%8C%87%E9%92%88%E4%BB%8E%E6%AD%A4%E9%81%BF%E5%BC%80%E5%88%9A%E7%94%A8%E8%BF%87%E7%9A%84%E8%B7%AF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>与 <a href="/cs/vipt-cache">VIPT</a> 无关：替换发生在命中/缺失判定之后，用的是物理标签那一组。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RRIP 的 SRRIP/BRRIP，下一课。也不把操作系统的页面 LRU 与 cache 行 LRU 写成同一个结构——页替换是 OS 课，虽然栈直觉相同。预取填入该标成 MRU 还是 LRU，影响污染，是预取课。</p><p>后课默认：组相联默认 PLRU 或真 LRU；扫描式工作集会打穿 LRU。再引用间隔预测是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>真 LRU 逼近 Belady，路多则用 PLRU 降位数。</li><li>扫描访问让 LRU 颠簸，这是 RRIP 的动机。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Belady MIN。</li></ul>',6))])}const h=o(R,[["render",d]]);export{m as __pageData,h as default};
